import React, { useState, useMemo } from 'react';

function UseMemoHook() {
  const [count, setCount] = useState(0);
  const [color, setColor] = useState("blue");

  function getNumber() {
    console.log("getNumber function called");
    return count * 10;
  }
  const myNumber = useMemo(() => getNumber(), [count]);

  return (
    <>
      <h1>useMemo() hook</h1>
      <h2>Count: {count}</h2>
      <button onClick={() => setCount(count + 1)}>Change Count</button>

      <div style={{ background: color, height: "200px", width: "300px" }}></div>
      <button onClick={() => setColor(color === "blue" ? "red" : "blue")}>Change Color</button>

      <h2>Number: {myNumber}</h2>
    </>
  );
}

export default UseMemoHook;
